css:
.container {
  width: 100%;
  height: 100%;
  position: relative;
  background: #f0f0f0;
  overflow: hidden;
}

.container::before,
.container::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
      circle at top left,
      rgba(255, 200, 150, 0.6) 10%,
      transparent 50%
    ),
    radial-gradient(
      circle at bottom right,
      rgba(100, 150, 255, 0.6) 10%,
      transparent 50%
    ),
    repeating-linear-gradient(
      45deg,
      rgba(255, 100, 100, 0.3),
      rgba(255, 100, 100, 0.3) 30px,
      transparent 30px,
      transparent 60px
    );
  z-index: 0;
}

.container .shape {
  position: absolute;
  width: 200px;
  height: 200px;
  background: linear-gradient(135deg, #ff7f50, #ff6347);
  clip-path: polygon(50% 0%, 100% 100%, 0% 100%);
  animation: rotateShape 5s infinite linear;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

@keyframes rotateShape {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

.container .shape:nth-child(2) {
  width: 150px;
  height: 150px;
  background: linear-gradient(135deg, #6a5acd, #8a2be2);
  top: 20%;
  left: 30%;
  clip-path: ellipse(50% 50% at 50% 50%);
  transform: translate(-50%, -50%) rotate(45deg);
}

.container .shape:nth-child(3) {
  width: 350px;
  height: 350px;
  background: linear-gradient(45deg, #ff1493, #ff6347);
  top: 70%;
  left: 70%;
  clip-path: polygon(10% 10%, 90% 10%, 100% 90%, 0% 90%);
  transform: translate(-50%, -50%) rotate(-30deg);
}
